  const start = (page - 1) * pageSize;
  const paginated = sorted.slice(start, start + pageSize);

  // Handle sort click
  const handleSort = (key) => {
    if (sortKey === key) {
      setSortOrder(sortOrder === "asc" ? "desc" : "asc");
    } else {
      setSortKey(key);
      setSortOrder("asc");
    }
  };

  // Reset page when filter changes
